        cg.generateTaskInit(NamingCzar.fortressBaseTask, init, freeVars);

        cg.generateTaskCompute(className, x, result);

        cg.cw.dumpClass(classFileName, xldata);

        this.lexEnv = restoreFromTaskLexEnv(cg.lexEnv, this.lexEnv);
