public void forLocalVarDecl(LocalVarDecl d) {
    debug("forLocalVarDecl", d);

    List<LValue> lhs = d.getLhs();
    int n = lhs.size();
    List<VarCodeGen> vcgs = new ArrayList(n);
    List<Type> lhs_types = new ArrayList(n);
