        if (!((TupleExpr)rhs).getVarargs().isSome() &&
                ((TupleExpr)rhs).getKeywords().isEmpty() ) {
            if (((TupleExpr)rhs).getExprs().size() == n)
                rhss = ((TupleExpr)rhs).getExprs();
